<script setup lang="ts">
import { toast } from '~/components/ui/sonner'
import type { Pipeline, PipelineItem, StageHistoryEntry } from '~/types/pipeline'

definePageMeta({ middleware: ['auth', 'onboarding', 'subscription', 'terms'] })
const route = useRoute(); const store = usePipelineStore(); const clientStore = useClientStore(); const router = useRouter()
const pipeline = ref<Pipeline | null>(null); const item = ref<PipelineItem | null>(null); const show = ref(false); const history = ref<StageHistoryEntry[]>([]); const historyTitle = ref(''); const historyLoading = ref(false); const error = ref<unknown>(null); const offline = ref(false); const announcement = ref('')
function statusOf(cause: unknown) { return store.statusOf(cause) }
function setOffline() { offline.value = !navigator.onLine }
async function load() { error.value = null; try { pipeline.value = await store.fetchPipeline(String(route.params.id)); await Promise.all([store.fetchItems(String(route.params.id)), clientStore.fetchClients({ per_page: 100 })]) } catch (cause) { error.value = cause } }
onMounted(() => { setOffline(); window.addEventListener('offline', setOffline); window.addEventListener('online', setOffline); void load() })
onBeforeUnmount(() => { window.removeEventListener('offline', setOffline); window.removeEventListener('online', setOffline) })
async function save(payload: import('~/types/pipeline').PipelineItemInput) { try { if (item.value) await store.updateItem(item.value.id, payload); else await store.createItem(payload); show.value = false; item.value = null; await store.fetchItems(pipeline.value!.id); toast.success('Intake item saved.'); announcement.value = 'Intake item saved.' } catch (cause) { toast.error(statusOf(cause) === 409 ? 'This intake item changed. Refresh and review it before saving.' : 'Could not save. Your draft is still here.') } }
async function move(target: PipelineItem, stage: string) { try { const moved = await store.moveItem(target, stage); await store.fetchItems(pipeline.value!.id); const name = pipeline.value!.stages.find(candidate => candidate.id === (moved?.stage_id ?? stage))?.name ?? 'the new stage'; announcement.value = `${target.title} moved to ${name}.`; toast.success(`Moved to ${name}.`) } catch (cause) { await store.fetchItems(pipeline.value!.id); toast.error(statusOf(cause) === 409 ? 'This intake item changed. The board was refreshed; review it and retry.' : 'Could not move the item. No changes were made.') } }
async function openHistory(target: PipelineItem) { historyTitle.value = target.title; historyLoading.value = true; try { history.value = await store.fetchHistory(target.id) } catch { history.value = []; toast.error('History could not load. Retry later.') } finally { historyLoading.value = false } }
</script>
<template>
  <main class="mx-auto w-full max-w-7xl px-4 pt-8 pb-6 sm:px-6"><AppPageHeader :title="pipeline?.name ?? 'Pipeline'" description="Intake pipeline board"><template #breadcrumb><NuxtLink to="/crm" class="hover:text-foreground">CRM</NuxtLink><span aria-hidden="true"> / </span>{{ pipeline?.name ?? 'Pipeline' }}</template><template #actions><Button variant="outline" class="min-h-11" @click="router.push('/crm/pipelines')">Settings</Button><Button class="min-h-11" :disabled="!pipeline || offline || store.saving" @click="item = null; show = true">New intake</Button></template></AppPageHeader><div v-if="offline" class="mt-4 rounded-lg border border-amber-500/40 bg-amber-500/10 p-3 text-sm" role="status">You are offline. Changes are disabled until the connection returns.</div><div v-if="error" class="surface-inset mt-5 py-16 text-center"><h2 class="text-lg font-semibold">Pipeline unavailable</h2><p class="mt-2 text-sm text-muted-foreground">{{ statusOf(error) === 403 ? 'You do not have permission to view this pipeline.' : statusOf(error) === 401 ? 'Your session has ended. Sign in again to continue.' : 'The pipeline could not load. Check your connection and try again.' }}</p><Button v-if="statusOf(error) === 401" class="mt-5 min-h-11" @click="navigateTo('/login')">Sign in</Button><Button v-else-if="statusOf(error) !== 403" variant="outline" class="mt-5 min-h-11" @click="load">Retry</Button></div><PipelineBoard v-else-if="pipeline" :pipeline="pipeline" :items="store.items" :loading="store.itemsLoading || store.loading" :busy="store.saving || offline" :error="store.itemsError" :announcement="announcement" @retry="load" @edit="item = $event; show = true" @move="move" @history="openHistory" /><PipelineItemForm v-if="show && pipeline" :pipeline="pipeline" :clients="clientStore.clients" :item="item" :busy="store.saving" :offline="offline" @submit="save" @cancel="show = false; item = null" /><div v-if="historyTitle" class="fixed inset-0 z-50 flex items-end justify-center bg-foreground/30 sm:items-center sm:p-4"><section role="dialog" aria-modal="true" aria-labelledby="detail-history-title" class="w-full rounded-t-2xl bg-card p-5 sm:max-w-lg sm:rounded-2xl"><div class="flex items-center justify-between gap-3"><h2 id="detail-history-title" class="text-lg font-semibold">History · {{ historyTitle }}</h2><Button variant="ghost" class="min-h-10" @click="historyTitle = ''">Close</Button></div><div v-if="historyLoading" class="mt-4 space-y-2" aria-busy="true"><Skeleton class="h-10" /><Skeleton class="h-10" /></div><p v-else-if="!history.length" class="mt-5 text-sm text-muted-foreground">No stage transitions recorded yet.</p><ol v-else class="mt-5 grid gap-3"><li v-for="entry in history" :key="entry.id" class="rounded-lg border p-3 text-sm"><p>{{ entry.previous_stage?.name ?? 'Created' }} → {{ entry.new_stage?.name ?? 'Unknown stage' }}</p><p class="mt-1 text-xs text-muted-foreground">{{ entry.actor?.name ?? 'Practice member' }} · {{ new Date(entry.created_at).toLocaleString() }}</p></li></ol></section></div></main>
</template>
